CREATE TABLE IF NOT EXISTS creative_script_packages(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,plan_id UUID NOT NULL REFERENCES creative_plans(id) ON DELETE CASCADE,version INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'awaiting_review' CHECK(status IN ('awaiting_review','approved','rejected')),model_id TEXT NOT NULL,pricing_free_verified BOOLEAN NOT NULL DEFAULT false,content JSONB NOT NULL,research JSONB NOT NULL DEFAULT '{}',confidence JSONB NOT NULL DEFAULT '{}',validation JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),reviewed_by TEXT,review_notes TEXT,reviewed_at TIMESTAMPTZ,UNIQUE(project_id,plan_id,version),CHECK(pricing_free_verified=true));
CREATE INDEX IF NOT EXISTS creative_script_packages_project_created_idx ON creative_script_packages(project_id,created_at DESC);
